			}
			name := fmt.Sprintf("code_fence_%d_%s", fenceIndex, lang)
			entities = append(entities, simpleFallbackEntity("code_fence", name, "markdown code fence "+lang, i+1, i+1, strings.TrimSpace(line)))
		}
	}
	return entities
}

