251			// Objective-C classes are canonically anchored at their .h header
252			// (`@interface Foo : NSObject` lives there; the .m holds the
253			// @implementation), so sniffed headers parse with the vendored
254			// tree-sitter-objc grammar like .m files instead of falling back to
255			// inventory. Headers that don't sniff keep the C/C++ routing below.
256			spec = treeSitterLanguages[".m"]
